169	    public Result<List<HttpRequest<BidRequest>>> makeHttpRequests(BidRequest bidRequest) {
170	        final List<HttpRequest<BidRequest>> httpRequests = new ArrayList<>();
171	        final List<BidderError> errors = new ArrayList<>();
172	
173	        final List<Imp> imps = extractValidImps(bidRequest, errors);
174	        if (CollectionUtils.isEmpty(imps)) {
175	            errors.add(BidderError.of("There are no valid impressions to create bid request to rubicon bidder",
176	                    BidderError.Type.bad_input));
177	            return Result.of(Collections.emptyList(), errors);
178	        }
179	        final Map<Imp, ExtPrebid<ExtImpPrebid, ExtImpRubicon>> impToImpExt =
180	                parseRubiconImpExts(imps, errors);
181	        final String impLanguage = firstImpExtLanguage(impToImpExt.values());
182	
183	        for (Map.Entry<Imp, ExtPrebid<ExtImpPrebid, ExtImpRubicon>> impToExt : impToImpExt.entrySet()) {
184	            try {
185	                final Imp imp = impToExt.getKey();
186	                final ExtPrebid<ExtImpPrebid, ExtImpRubicon> ext = impToExt.getValue();
187	                final BidRequest singleRequest = createSingleRequest(
188	                        imp, ext.getPrebid(), ext.getBidder(), bidRequest, impLanguage);
189	                final String body = mapper.encode(singleRequest);
190	                httpRequests.add(HttpRequest.<BidRequest>builder()
191	                        .method(HttpMethod.POST)
192	                        .uri(makeUri(bidRequest))
193	                        .body(body)
194	                        .headers(headers)
195	                        .payload(singleRequest)
196	                        .build());
197	            } catch (PreBidException e) {
198	                errors.add(BidderError.badInput(e.getMessage()));
199	            }
200	        }
201	
202	        return Result.of(httpRequests, errors);
203	    }
