+        if (isVideo(imp)) {
+            builder
+                    .banner(null)
+                    .video(makeVideo(imp, extRubicon.getVideo(), extPrebid, referer(site)));
+        } else {
+            builder
+                    .banner(makeBanner(imp, overriddenSizes(extRubicon)))
